        "url": "https://www.baidu.com/s?wd=%E8%B0%A2%E9%9C%86%E9%94%8B%E6%82%BC%E5%BF%B5%E7%88%B6%E4%BA%B2%EF%BC%9A%E4%B8%8D%E7%94%A8%E5%93%AD+%E4%BB%96%E8%A7%89%E5%BE%97%E4%B8%8D%E6%BD%87%E6%B4%92&sa=fyb_news&rsv_dl=fyb_news",
        "description": "7月20日，谢霆锋回应父亲谢贤去世：非常遗憾向大家宣布，我的父亲谢贤已经离开我们了。他把自己的一生都奉献给影视与娱乐，希望把欢乐和笑容带给每一位观众。大家如果想起四哥、想起我父亲，不用哭，也不必太伤心，他会觉得那样不够潇洒。",
        "paragraphs": [
          "7月20日，谢霆锋回应父亲谢贤去世：非常遗憾向大家宣布，我的父亲谢贤已经离开我们了。他把自己的一生都奉献给影视与娱乐，希望把欢乐和笑容带给每一位观众。大家如果想起四哥、想起我父亲，不用哭，也不必太伤心，他会觉得那样不够潇洒。"
        ],
